    const cells = raw.split("\t").map(s => s.trim()).filter(Boolean); if (!cells.length) continue;
    if (cells.length === 1 && /^(?:[-*•+]|\d+[.)]|\[\s*[x✓✔v]?\s*\]|\s)*$/i.test(cells[0])) continue;  // a bullet or number alone
    if (/^(?:(?:[-*•+]|\d+[.)])\s*)*(?:\[\s*\]|☐|□|✗|✘|❌|✖)/.test(cells[0]) ||
        cells.some(c => /^(?:no|false|not found|missing|☐|□|✗|✘|❌|✖|0|-|\[\s*\])$/i.test(c))) { skip++; marked = true; continue; }
    if (/^(?:(?:[-*•+]|\d+[.)])\s*)*\[\s*[x✓✔v]\s*\]/i.test(cells[0]) || cells.some(c => /^(?:yes|true|found|have|owned|✓|✔)$/i.test(c))) marked = true;
